{"code":"const searchResult = await callTool('search_flights', {from: 'BLR', to: 'SYD', maxPrice: 40000});
const flights = searchResult.flights || [];
let qualified = [];
for (const flight of flights) {
  const baggage = await callTool('get_baggage_policy', {flightId: flight.id});
  if (baggage.checkedKg >= 20) {
    qualified.push({id: flight.id, airline: flight.airline, price: flight.price, checkedKg: baggage.checkedKg});
  }
  if (qualified.length >= 10) break; // limit to avoid excessive calls
}
// sort by price ascending (should already be sorted, but ensure)
qualified.sort((a,b)=> a.price - b.price);
const top3 = qualified.slice(0,3);
return {options: top3, sampleData: true};"}

